```go
package main

import (
	"context"
	"fmt"
	"log"
	"os"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
	// Create an AWS session
	sess, err := session.NewSession(&aws.Config{Region: aws.String(os.Getenv("AWS_REGION"))}, nil)
	if err != nil {
		log.Fatal(err)
	}

	// Create an EC2 client
	ec2Client := ec2.New(sess)

	// Get all EBS snapshots
 DescribeSnapshotsInput := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("status"),
			 Values: []*string{
					aws.String("completed"),
				},
			},
		},
	}
	descSnapsResp, err := ec2Client.DescribeSnapshots(context.TODO(), DescribeSnapshotsInput)
	if err != nil {
		log.Fatal(err)
	}

	// Loop through snapshots and delete old ones
	for _, snap := range descSnapsResp.Snapshots {
		tag := ""
		for _, t := range snap.Tags {
			if *t.Key == "backup_type" {
				tag = *t.Value
				break
			}
		}

		switch *tag {
		case "monthly":
			// Keep the last 14 monthly snapshots
			if len(descSnapsResp.Snapshots) > 14 {
				err := ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: snap.SnapshotId})
				if err != nil {
					log.Println(err)
				}
			}
		case "daily":
			// Keep the last 10 daily snapshots
			if len(descSnapsResp.Snapshots) > 10 {
				err := ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: snap.SnapshotId})
				if err != nil {
					log.Println(err)
				}
			}
		case "weekly":
			// Keep the last 4 weekly snapshots
			if len(descSnapsResp.Snapshots) > 4 {
				err := ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: snap.SnapshotId})
				if err != nil {
					log.Println(err)
				}
			}
		case "yearly":
			// Keep only 1 yearly snapshot
			err := ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: snap.SnapshotId})
			if err != nil {
				log.Println(err)
			}
		default:
			log.Println("Skipping unknown tag:", tag)
		}
	}

	return nil, nil
}

func main() {
	lambda.Start(handler)
}
