```c
#include <pigpio.h>

#define PIN 12 // GPIO pin 12

int main() {
    // Initialize the pigpio library
    gpioInitialise();

    // Set pin 12 as an output
    gpioSetup(PIN, OUTPUT);

    // Set the initial state of pin 12 to LOW
    gpioWrite(PIN, 0);

    // Main program loop
    while (true) {
        // Set pin 12 to HIGH for 1 second
        gpioWrite(PIN, 1);
        delay(1000);

        // Set pin 12 to LOW for 1 second
        gpioWrite(PIN, 0);
        delay(1000);
    }

    // Clean up
    gpioTerminate();

    return 0;
}
```
